date && cat > test-lanterns.mjs <<'EOF'
// Test only: adds the fittings' porch lanterns (12,3,6),(14,3,6) and their chains to a copy, to check walking and light.
import { load, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const g = load("build.nbt");
for (const x of [12, 14]) {
  g.set(x, 3, 6, "lantern", { hanging: "true" });
  g.set(x, 4, 6, ...B.chain("y"));
}
g.save("test-lanterns.nbt");
console.log("saved test-lanterns.nbt");
EOF
node test-lanterns.mjs && MCD="/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs" && node $MCD room test-lanterns.nbt --rooms rooms.json --only "Front porch" 2>&1 | head -30

